// Package route holds one typed member per operation that the Village API and
// Local API documents declare. A server mounts a handler from a member and a
// client builds a request path from it, so neither side writes an endpoint path
// as a string literal.
//
// The members are generated by `go run ./cmd/schema-gen` from the same built
// documents the module publishes (routes_gen.go). This file holds only the
// types the generated members use. Each operation becomes:
//
//   - a Route value named <API><OperationID>, for example
//     VillageGetPullRequestAttachment, carrying the method, the pattern and the
//     operationId;
//   - when the pattern has path parameters, a path builder named
//     <API><OperationID>Path whose parameters follow the document's order and
//     types. It returns a *PathSegmentError for a string value that is empty,
//     "." or "..";
//   - an entry in the ordered set AllVillage or AllLocal.
package route

import (
	"fmt"
	"net/url"
	"strconv"
)

// Method is the closed set of HTTP methods the documents declare.
type Method string

const (
	MethodGet    Method = "GET"
	MethodPost   Method = "POST"
	MethodPut    Method = "PUT"
	MethodPatch  Method = "PATCH"
	MethodDelete Method = "DELETE"
)

// AllMethods is the canonical ordered closed set of methods. Members of
// AllVillage and AllLocal that share a pattern are ordered by it.
var AllMethods = []Method{MethodGet, MethodPost, MethodPut, MethodPatch, MethodDelete}

// String returns the method as it is sent on the wire.
func (m Method) String() string { return string(m) }

// IsValid reports whether m is a member of AllMethods.
func (m Method) IsValid() bool {
	for _, known := range AllMethods {
		if m == known {
			return true
		}
	}
	return false
}

// Route is one declared operation. Its fields are unexported, so only the
// generated members exist; the zero value is not a route.
type Route struct {
	method      Method
	pattern     string
	operationID string
}

// Method returns the HTTP method the document declares for the operation.
func (r Route) Method() Method { return r.method }

// Pattern returns the document's path template, for example
// "/api/v1/pulls/{owner}/{name}/{number}". The {name} parameter syntax is also
// the syntax of chi and of net/http's ServeMux, so a router takes it unchanged.
func (r Route) Pattern() string { return r.pattern }

// OperationID returns the document's operationId, for example
// "getPullRequestAttachment".
func (r Route) OperationID() string { return r.operationID }

// MuxPattern returns the method and the pattern in net/http's ServeMux form,
// for example "GET /api/v1/pulls/{owner}/{name}/{number}".
func (r Route) MuxPattern() string { return string(r.method) + " " + r.pattern }

// pathSegment escapes one string path parameter as a single path segment.
func pathSegment(value string) string { return url.PathEscape(value) }

// intPathSegment writes one integer path parameter in decimal.
func intPathSegment(value int) string { return strconv.Itoa(value) }

// PathSegmentError reports a path parameter value that a path builder refuses:
// an empty value, ".", or "..". Each is a dot or empty path segment, which
// clients and proxies resolve or drop, so the request would reach a different
// endpoint than the operation named.
type PathSegmentError struct {
	// OperationID is the operationId of the route whose path was being built.
	OperationID string
	// Pattern is the route's path template.
	Pattern string
	// Parameter is the name of the refused path parameter.
	Parameter string
	// Value is the refused value: "", "." or "..".
	Value string
}

// Error describes the refused value, why it is refused, where, and the fix.
// The TypeScript path() builder throws the same text.
func (e *PathSegmentError) Error() string {
	got := "empty"
	if e.Value != "" {
		got = strconv.Quote(e.Value)
	}
	return fmt.Sprintf("route path for %s (%s) could not be built: parameter %q is %s; "+
		"a path segment that is empty, \".\" or \"..\" is resolved by clients and proxies, so the request would reach a different endpoint; "+
		"pass the identifier of the resource the parameter names.", e.OperationID, e.Pattern, e.Parameter, got)
}

// checkPathSegment refuses a string path parameter value that is not one
// addressable path segment.
func checkPathSegment(r Route, parameter, value string) error {
	switch value {
	case "", ".", "..":
		return &PathSegmentError{OperationID: r.operationID, Pattern: r.pattern, Parameter: parameter, Value: value}
	}
	return nil
}
